### `iam.tf`

```hcl
# ── IAM Policy: S3 Access (least-privilege) ────────

data "aws_iam_policy_document" "app_s3_access" {
  statement {
    sid    = "ListBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]
    resources = [aws_s3_bucket.app.arn]
  }

  statement {
    sid    = "ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["${aws_s3_bucket.app.arn}/*"]
  }

  statement {
    sid    = "KMSAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.s3.arn]
  }
}

resource "aws_iam_policy" "app_s3" {
  name        = "${local.name_prefix}-s3-access"
  description = "Least-privilege S3 access for ${local.name_prefix} application"
  policy      = data.aws_iam_policy_document.app_s3_access.json
}

# ── IAM Policy: RDS Access ─────────────────────────

data "aws_iam_policy_document" "app_rds_access" {
  statement {
    sid    = "RDSConnect"
    effect = "Allow"
    actions = [
      "rds-db:connect",
    ]
    resources = [
      "arn:aws:rds-db:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:dbuser:${aws_db_instance.app.resource_id}/${var.db_username}",
    ]
  }
}

resource "aws_iam_policy" "app_rds" {
  name        = "${local.name_prefix}-rds-access"
  description = "RDS IAM authentication for ${local.name_prefix}"
  policy      = data.aws_iam_policy_document.app_rds_access.json
}

# ── Dev: IAM User with programmatic access ─────────

resource "aws_iam_user" "app" {
  count = var.environment == "dev" ? 1 : 0

  name = "${local.name_prefix}-app-user"

  tags = {
    Name = "${local.name_prefix}-app-user"
  }
}

resource "aws_iam_user_policy_attachment" "app_s3" {
  count = var.environment == "dev" ? 1 : 0

  user       = aws_iam_user.app[0].name
  policy_arn = aws_iam_policy.app_s3.arn
}

resource "aws_iam_user_policy_attachment" "app_rds" {
  count = var.environment == "dev" ? 1 : 0

  user       = aws_iam_user.app[0].name
  policy_arn = aws_iam_policy.app_rds.arn
}

resource "aws_iam_access_key" "app" {
  count = var.environment == "dev" ? 1 : 0

  user = aws_iam_user.app[0].name
}

# ── Prod: IAM Role with OIDC trust (IRSA) ──────────

data "aws_iam_policy_document" "oidc_assume" {
  count = var.environment == "prod" ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider_arn, "/^(.*provider\\/)/", "")}:sub"
      values   = ["system:serviceaccount:${var.eks_namespace}:${var.eks_service_account_name}"]
    }

    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider_arn, "/^(.*provider\\/)/", "")}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "app" {
  count = var.environment == "prod" ? 1 : 0

  name               = "${local.name_prefix}-app-role"
  assume_role_policy = data.aws_iam_policy_document.oidc_assume[0].json

  tags = {
    Name = "${local.name_prefix}-app-role"
  }
}

resource "aws_iam_role_policy_attachment" "app_s3" {
  count = var.environment == "prod" ? 1 : 0

  role       = aws_iam_role.app[0].name
  policy_arn = aws_iam_policy.app_s3.arn
}

resource "aws_iam_role_policy_attachment" "app_rds" {
  count = var.environment == "prod" ? 1 : 0

  role       = aws_iam_role.app[0].name
  policy_arn = aws_iam_policy.app_rds.arn
}
```

