### `outputs.tf`

```hcl
# ── S3 ─────────────────────────────────────────────

output "bucket_name" {
  description = "Name of the S3 bucket"
  value       = aws_s3_bucket.app.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket"
  value       = aws_s3_bucket.app.arn
}

output "bucket_region" {
  description = "Region of the S3 bucket"
  value       = aws_s3_bucket.app.region
}

output "replica_bucket_arn" {
  description = "ARN of the replication destination bucket (prod only)"
  value       = var.enable_replication ? aws_s3_bucket.replica[0].arn : null
}

# ── RDS ────────────────────────────────────────────

output "db_endpoint" {
  description = "RDS instance endpoint"
  value       = aws_db_instance.app.endpoint
}

output "db_address" {
  description = "RDS instance hostname"
  value       = aws_db_instance.app.address
}

output "db_port" {
  description = "RDS instance port"
  value       = aws_db_instance.app.port
}

output "db_name" {
  description = "Name of the database"
  value       = aws_db_instance.app.db_name
}

output "db_arn" {
  description = "ARN of the RDS instance"
  value       = aws_db_instance.app.arn
}

output "db_resource_id" {
  description = "RDS resource ID (for IAM authentication)"
  value       = aws_db_instance.app.resource_id
}

# ── IAM ────────────────────────────────────────────

output "iam_role_arn" {
  description = "ARN of the IAM role (prod)"
  value       = var.environment == "prod" ? aws_iam_role.app[0].arn : null
}

output "iam_user_name" {
  description = "Name of the IAM user (dev)"
  value       = var.environment == "dev" ? aws_iam_user.app[0].name : null
}

output "iam_access_key_id" {
  description = "Access key ID for the IAM user (dev)"
  value       = var.environment == "dev" ? aws_iam_access_key.app[0].id : null
  sensitive   = true
}

output "iam_secret_access_key" {
  description = "Secret access key for the IAM user (dev)"
  value       = var.environment == "dev" ? aws_iam_access_key.app[0].secret : null
  sensitive   = true
}

# ── KMS ────────────────────────────────────────────

output "s3_kms_key_arn" {
  description = "ARN of the S3 KMS key"
  value       = aws_kms_key.s3.arn
}

output "rds_kms_key_arn" {
  description = "ARN of the RDS KMS key"
  value       = aws_kms_key.rds.arn
}

# ── Connection String (for secret store) ───────────

output "db_connection_string" {
  description = "PostgreSQL connection string (store in secret manager)"
  value       = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.app.address}:${aws_db_instance.app.port}/${var.db_name}"
  sensitive   = true
}
```

