## Environment Configurations

### `environments/dev/main.tf`

```hcl
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

module "infrastructure" {
  source = "../../modules/app-infrastructure"

  environment  = "dev"
  project_name = var.project_name
  region       = var.region

  # S3
  bucket_name        = var.bucket_name
  enable_replication = false

  # RDS
  db_instance_class         = "db.t3.micro"
  db_name                   = var.db_name
  db_username               = var.db_username
  db_password               = var.db_password
  db_multi_az               = false
  db_allocated_storage      = 20
  db_backup_retention_period = 7

  tags = {
    Team       = "platform"
    CostCenter = "engineering"
  }
}

output "bucket_name" {
  value = module.infrastructure.bucket_name
}

output "db_endpoint" {
  value = module.infrastructure.db_endpoint
}

output "db_connection_string" {
  value     = module.infrastructure.db_connection_string
  sensitive = true
}

output "iam_access_key_id" {
  value     = module.infrastructure.iam_access_key_id
  sensitive = true
}

output "iam_secret_access_key" {
  value     = module.infrastructure.iam_secret_access_key
  sensitive = true
}
```

