### `environments/prod/main.tf`

```hcl
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

module "infrastructure" {
  source = "../../modules/app-infrastructure"

  environment  = "prod"
  project_name = var.project_name
  region       = var.region

  # S3
  bucket_name        = var.bucket_name
  enable_replication = true
  replication_region = "us-west-2"

  # RDS
  db_instance_class          = "db.t3.medium"
  db_name                    = var.db_name
  db_username                = var.db_username
  db_password                = var.db_password
  db_multi_az                = true
  db_allocated_storage       = 50
  db_backup_retention_period = 30

  # IAM (IRSA)
  oidc_provider_arn        = var.oidc_provider_arn
  eks_namespace            = var.eks_namespace
  eks_service_account_name = var.eks_service_account_name

  tags = {
    Team       = "platform"
    CostCenter = "engineering"
    Compliance = "required"
  }
}

output "bucket_name" {
  value = module.infrastructure.bucket_name
}

output "replica_bucket_arn" {
  value = module.infrastructure.replica_bucket_arn
}

output "db_endpoint" {
  value = module.infrastructure.db_endpoint
}

output "db_connection_string" {
  value     = module.infrastructure.db_connection_string
  sensitive = true
}

output "iam_role_arn" {
  value = module.infrastructure.iam_role_arn
}
```

